import java.util.Scanner;
public class SearchArrayElement { public static void main(String[] args){Scanner s=new Scanner(System.in);System.out.print("Enter array size (1-100): ");if(!s.hasNextInt()){System.out.println("Enter a size from 1 to 100.");return;}int n=s.nextInt();if(n<1||n>100){System.out.println("Array size must be from 1 to 100.");return;}int[] a=new int[n];for(int i=0;i<n;i++){if(!s.hasNextInt()){System.out.println("Enter array values and one target.");return;}a[i]=s.nextInt();}if(!s.hasNextInt()){System.out.println("Enter one target whole number.");return;}int target=s.nextInt();if(s.hasNext()){System.out.println("Enter only the array values and target.");return;}int found=-1;for(int i=0;i<n;i++)if(a[i]==target){found=i;break;}System.out.println(found<0?"Not found":"Found at index "+found);}}
